import { join } from 'node:path';
import { Menu, nativeImage, Tray } from 'electron';
import type { SyncedAccount } from './api-client';
import { type Locale, trayTranslator } from './locale';
import { trayModel } from './tray-model';

/** The menu-bar / system-tray entry. Icons are generated by the build (`scripts/build.mjs`). */

export interface TrayController {
  update(accounts: readonly SyncedAccount[] | null): void;
  /** Redraws the tray in `locale` (the language the screens show). */
  setLocale(locale: Locale): void;
  destroy(): void;
}

export function createTray(opts: {
  assetsDir: string;
  locale: Locale;
  onRefresh(): void;
  onOpen(): void;
  onQuit(): void;
}): TrayController {
  const file =
    process.platform === 'darwin'
      ? join(opts.assetsDir, 'trayTemplate.png')
      : join(opts.assetsDir, 'tray.png');
  const image = nativeImage.createFromPath(file);
  if (process.platform === 'darwin') image.setTemplateImage(true);
  const tray = new Tray(image);
  let last: readonly SyncedAccount[] | null = null;
  let t = trayTranslator(opts.locale);

  const render = () => {
    const model = trayModel(last, new Date(), t);
    tray.setToolTip(model.tooltip);
    if (process.platform === 'darwin') tray.setTitle(model.title);
    tray.setContextMenu(
      Menu.buildFromTemplate([
        { label: model.headline, enabled: false },
        { type: 'separator' },
        { label: t('refresh'), click: opts.onRefresh },
        { label: t('open'), click: opts.onOpen },
        { type: 'separator' },
        { label: t('quit'), click: opts.onQuit },
      ]),
    );
  };
  tray.on('click', () => {
    if (process.platform !== 'darwin') opts.onOpen();
  });
  render();

  return {
    update(accounts) {
      last = accounts;
      render();
    },
    setLocale(locale) {
      t = trayTranslator(locale);
      render();
    },
    destroy() {
      tray.destroy();
    },
  };
}
